import pandas as pd
for c in ['AA','UA']:
 d=pd.read_csv(f'airlines/{c}.csv'); d['cancelled']=d.cancelled.astype(str).str.lower().eq('true')
 print('\n',c,'cancel vals',d.cancelled.value_counts().to_dict(),'missing actual',d.actual_dep.isna().sum())
 x=d[~d.cancelled].copy();
 def mins(s):
  h,m=map(int,s.split(':')); return h*60+m
 x['raw']=x.actual_dep.map(mins)-x.sched_dep.map(mins)
 print(x.raw.describe()); print(x.nsmallest(15,'raw')[['date','origin','dest','sched_dep','actual_dep','raw']].to_string(index=False)); print('large negative', (x.raw < -60).sum())

